WITH kept_keys AS (SELECT id FROM customers INTERSECT ALL SELECT id FROM customers WHERE segment IN ('Corporate', 'Consumer', 'SMB')), verified AS (SELECT s.* FROM customers s INNER JOIN kept_keys k ON s.id = k.id) SELECT DATE_TRUNC('MONTH', signup_date) AS activity_month, CASE WHEN age >= 61 THEN 'LARGE' ELSE 'SMALL' END AS age_tier, COUNT(*) FILTER (WHERE country = 'US') AS us_rows, BIT_OR(age) AS age_bit_or, AVG(credit_limit) AS avg_credit_limit, COUNT(*) FILTER (WHERE country = 'UK') AS uk_rows, COUNT(*) FILTER (WHERE city = 'New York') AS new_york_rows FROM verified GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', signup_date), CASE WHEN age >= 61 THEN 'LARGE' ELSE 'SMALL' END), (DATE_TRUNC('MONTH', signup_date)));
